-- Week 8: readable regular expression foundations.
DO $$
DECLARE c uuid; m integer;
BEGIN
 SELECT id INTO c FROM public.courses WHERE slug='python-foundations';
 IF c IS NULL THEN RAISE EXCEPTION 'Python Foundations course must exist'; END IF;
 INSERT INTO public.modules(course_id,month_number,title,tagline,description,capstone_title,is_free,order_index,status)
 VALUES(c,8,'Patterns in Text','Week 8 · Sessions 1–5','Build readable regular expressions and use them to recognize text formats.','A Clear Format Checker',false,8,'published')
 ON CONFLICT(course_id,month_number,order_index) DO UPDATE SET title=EXCLUDED.title,tagline=EXCLUDED.tagline,description=EXCLUDED.description,capstone_title=EXCLUDED.capstone_title,is_free=EXCLUDED.is_free,status=EXCLUDED.status RETURNING id INTO m;
 WITH d(n,title,analogy,body,q,opts,ans,why) AS (VALUES
 (1,'Describe a Pattern in Text','A form can describe the shape an answer must follow.','## Goal\nRecognize what a regular expression describes.\n\n## Plain explanation\nA regular expression, or regex, is a pattern used to find or check text. Python provides it in the built-in `re` module. For example, `r"cat"` describes those exact letters. `re.search` looks for a match anywhere; `re.fullmatch` requires the whole answer to match.\n\n## Example\n```python\nimport re\npattern = r"cat"\nprint(bool(re.fullmatch(pattern, "cat")))\nprint(bool(re.fullmatch(pattern, "catalog")))\n```\n\nThe first result is true; the second is false because extra letters remain.','Which function checks that the whole text fits a pattern?','["re.fullmatch", "re.search only", "print"]'::jsonb,0,'fullmatch requires the entire string to fit the pattern.'),
 (2,'Match Digits and Repeated Characters','A class code may need four digits after its letters.','## Goal\nRead digit and repetition symbols in a small pattern.\n\n## Plain explanation\nIn a regex, `\\d` means one digit from 0 through 9. `\\d{4}` means exactly four digits. A raw string such as `r"\\d{4}"` lets Python pass the backslash to the regex clearly. Use `re.fullmatch` when validating the complete answer.\n\n## Example\n```python\nimport re\nprint(bool(re.fullmatch(r"\\d{4}", "2026")))\nprint(bool(re.fullmatch(r"\\d{4}", "26")))\n```\n\nA matching shape does not prove the number has any real-world meaning.','What does `\\d{4}` mean?','["Exactly four digits", "Four letters", "Any four words"]'::jsonb,0,'The digit symbol repeated exactly four times requires four digits.'),
 (3,'Capture a Useful Part of a Match','Parentheses can mark a section to retrieve from a match.','## Goal\nUnderstand a capture group and retrieve its value.\n\n## Plain explanation\nParentheses in a regex group part of a pattern. When that group matches, Python can return its text. `group(1)` means the first parenthesized group. The raw pattern below captures the four digits.\n\n## Example\n```python\nimport re\nmatch = re.fullmatch(r"ID-(\\d{4})", "ID-2042")\nif match:\n    print(match.group(1))\n```\n\nThe output is `2042`. If there is no full match, `match` is `None`, so check it before asking for a group.','What does `group(1)` return here?','["The first captured part", "The whole Python file", "The pattern length"]'::jsonb,0,'group(1) returns the text matched by the first set of parentheses.'),
 (4,'Validate a Whole Answer','A gate checks every part of a ticket code, not only its beginning.','## Goal\nUse a regex as one clear input-format check.\n\n## Plain explanation\n`re.fullmatch` helps validate an entire string against a format. For an IPv4 address, matching four groups of digits is only the shape check. Each group also must be between 0 and 255, so split the work into understandable checks instead of relying on a long unexplained pattern. A matching format cannot prove an address is assigned or reachable.','Why is matching four number groups not enough to validate an IPv4 address?','["Each group must also be from 0 to 255", "IP addresses never contain digits", "Regex can only read letters"]'::jsonb,0,'The format requires each of the four numeric sections to be in the allowed range.'),
 (5,'Build a Readable Text Checker','A checklist makes each condition visible before a final decision.','## Goal\nCombine small pattern rules and explain what they check.\n\n## Plain explanation\nStart with examples that should pass and fail. Write one small check at a time, give each helper a clear name, and use a full match when the entire input must follow the format. In Working 9 to 5, for example, a pattern can recognize the written range shape, while separate logic validates and converts the hour values. For YouTube URLs, recognizing an ID does not confirm that a video exists.','What is a good first step before combining regex rules?','["Test small rules against clear examples", "Copy a long pattern without reading it", "Assume matching proves the data is real"]'::jsonb,0,'Small examples help learners see which rule accepts or rejects each input.')
 ), ins AS (
 INSERT INTO public.sessions(module_id,session_number,title,analogy_physical,content_markdown,starter_code,hints,xp_reward,order_index,duration_minutes,quick_check)
 SELECT m,n,title,analogy,replace(replace(replace(body,'For YouTube URLs, recognizing an ID does not confirm that a video exists.','For YouTube URLs, recognizing an ID does not confirm that a video exists. Response Validation instead uses an external email validation package and does not use re.'),chr(92)||'n',chr(10)),chr(92)||chr(92)||'d',chr(92)||'d'),replace('import re\n\n# Try a small pattern with re.fullmatch',chr(92)||'n',chr(10)),'["Read one symbol at a time.","Use raw strings for patterns with backslashes.","Test an input that should pass and one that should fail."]'::jsonb,50,n,15,jsonb_build_object('question',replace(q,chr(92)||chr(92)||'d',chr(92)||'d'),'options',opts) FROM d
 ON CONFLICT(module_id,session_number) DO UPDATE SET title=EXCLUDED.title,analogy_physical=EXCLUDED.analogy_physical,content_markdown=EXCLUDED.content_markdown,starter_code=EXCLUDED.starter_code,hints=EXCLUDED.hints,xp_reward=EXCLUDED.xp_reward,order_index=EXCLUDED.order_index,duration_minutes=EXCLUDED.duration_minutes,quick_check=EXCLUDED.quick_check RETURNING id,session_number
 ) INSERT INTO private.session_quick_check_answers(session_id,correct_option,explanation) SELECT ins.id,d.ans,d.why FROM ins JOIN d ON d.n=ins.session_number ON CONFLICT(session_id) DO UPDATE SET correct_option=EXCLUDED.correct_option,explanation=EXCLUDED.explanation;
END $$;
